// древо технологий (NODES) + индекс NODE — из _tech.gen.js (канон server/sim/tech-data.js)
// поля узла: id,col,x,y,ic,name,req[],g(голда),t(сек), эффекты a/d/e/s/p, v{tr,td,…}(×), u(разблок), slot(+слот)
let techDone=[], techRes=[], techCache=[];   // [fid]: Set изученных / активные {id,t} / кэш бонусов
function recomputeTech(fid){
  const add={atk:0,def:0,eco:0,speed:0,prod:0,tr:0,td:0,sh:0,ph:0,sr:0,bd:0,cc:0};
  const flags=new Set(); let slots=1;
  for(const id of (techDone[fid]||[])){ const n=NODE[id]; if(!n)continue;
    if(n.a)add.atk+=n.a; if(n.d)add.def+=n.d; if(n.e)add.eco+=n.e; if(n.s)add.speed+=n.s; if(n.p)add.prod+=n.p;
    if(n.v)for(const k in n.v)add[k]=(add[k]||0)+n.v[k];
    if(n.u)flags.add(n.u);
    if(n.slot)slots+=n.slot;
  }
  techCache[fid]={add,flags,slots};
}
function techMul(o,branch){const c=techCache[o], m=(typeof FACTION_MODS!=='undefined'&&FACTION_MODS[branch])||1; return (1+(c?(c.add[branch]||0):0)+heroAdd(o,branch))*m;}  // atk/def/eco/speed/prod (+ герои) × фракц.мод (как на сервере)
function techVal(o,key){const c=techCache[o];return 1+(c?(c.add[key]||0):0)+heroAdd(o,key);}          // tr/td/sh/ph/sr/bd/cc (+ герои)
function techFlag(o,flag){const c=techCache[o];return !!(c&&c.flags.has(flag));}
function slotCount(o){const c=techCache[o];return c?c.slots:1;}
function techHas(o,id){return techDone[o]&&techDone[o].has(id);}
function nodeReady(fid,n){return n.req.every(r=>techHas(fid,r));}
function initTech(){
  techDone=FACTIONS.map(()=>new Set()); techRes=FACTIONS.map(()=>[]); techCache=[];
  FACTIONS.forEach((f,i)=>recomputeTech(i));
}
