function _pctFill(el){const f=(el.value-el.min)/(el.max-el.min)*100;el.style.backgroundSize=f+'% 100%';}
document.getElementById('pct').oninput=e=>{sendPct=e.target.value/100;document.getElementById('pctVal').textContent=e.target.value+'%';_pctFill(e.target);};
_pctFill(document.getElementById('pct'));

